use criterion::{criterion_group, criterion_main, Criterion};
use fast_paillier::{precomputed_table::PrecomputeTable, DecryptionKey};
use once_cell::sync::Lazy;
use rug::Integer;
use std::sync::Mutex;

static BLOCK_SIZE: usize = 15;
static POW_SIZE: usize = 448;
static BASE_AS_STR: &'static str = "";
static MODULO_AS_STR: &'static str = " ";
// [INFO] base bits: 4086
// [INFO] modulo bits: 4091

static PRECOMPUTE_TABLE: Lazy<Mutex<PrecomputeTable>> = Lazy::new(|| {
    let base = Integer::from_str_radix(BASE_AS_STR, 10).unwrap();
    let modulo = Integer::from_str_radix(MODULO_AS_STR, 10).unwrap();
    Mutex::new(PrecomputeTable::new_dp(base, BLOCK_SIZE, POW_SIZE, modulo))
});

fn get_precompute_table() -> &'static Mutex<PrecomputeTable> {
    &PRECOMPUTE_TABLE
}

fn encryption_with_caculated_precompute_table(c: &mut Criterion) {
    let dk = DecryptionKey::sample_112();
    let ek = dk.encryption_key();

    let precompute_table = get_precompute_table();

    let mut rng = rand_dev::DevRng::new();

    c.bench_function("encryption_with_caculated_precompute_table", |b| {
        b.iter(|| {
            let m = Integer::from(10);
            let table = precompute_table.lock().unwrap();
            let _ = ek
                .encrypt_with_precompute_table(&mut rng, &table, &m)
                .unwrap();
        })
    });
}

fn encryption_with_new_precompute_table(c: &mut Criterion) {
    let dk = DecryptionKey::sample_112();
    let ek = dk.encryption_key();

    let mut rng = rand_dev::DevRng::new();

    c.bench_function("encryption_with_new_precompute_table", |b| {
        b.iter(|| {
            let m = Integer::from(10);
            let base = Integer::from_str_radix(BASE_AS_STR, 10).unwrap();
            let modulo = Integer::from_str_radix(MODULO_AS_STR, 10).unwrap();
            let precompute_table = PrecomputeTable::new_dp(base, BLOCK_SIZE, POW_SIZE, modulo);

            let _ = ek
                .encrypt_with_precompute_table(&mut rng, &precompute_table, &m)
                .unwrap();
        })
    });
}

criterion_group!(
    benches,
    encryption_with_new_precompute_table,
    encryption_with_caculated_precompute_table
);
criterion_main!(benches);
